package manufacturer.scheduling.menu;
import manufacturer.productionrequest.model.ProductionRequest; import manufacturer.scheduling.model.ProductCategoryNode; import manufacturer.scheduling.service.ProductionSchedulingService; import java.sql.SQLException; import java.util.*;
/** Reusable collection-backed scheduling view; refreshes from MySQL before display. */
public class ProductionSchedulingMenu {
 private final ProductionSchedulingService service=new ProductionSchedulingService(); private final Scanner scanner=new Scanner(System.in);
 public void showMenu(int id){boolean run=true;while(run){System.out.println("\n--- Production Scheduling ---\n1. View Production Queue\n2. View Priority Queue\n3. Process Next Production Request\n4. View Production Schedule\n5. Back");System.out.print("Enter Choice: ");try{service.refreshFromDatabase(id);switch(scanner.nextLine().trim()){case"1":requests(service.getNormalRequestQueue());break;case"2":requests(service.getPriorityRequestQueue());break;case"3":ProductionRequest r=service.pollNextPriorityRequest();System.out.println(r==null?"No pending request.":"Next request: "+r.getRequestId()+" - "+r.getProductName()+" ("+r.getPriority()+")");break;case"4":System.out.println("Orders: "+service.getProductionOrders().size()+", History: "+service.getProductionHistory().size());for(ProductCategoryNode n:service.getProductCategoryTree())System.out.println(n.getCategoryName()+": "+n.getProducts().size()+" product(s)");break;case"5":run=false;break;default:throw new IllegalArgumentException("Choose 1 to 5.");}}catch(IllegalArgumentException|SQLException e){System.out.println("Error: "+e.getMessage());}}}
 private void requests(List<ProductionRequest>a){if(a.isEmpty()){System.out.println("No pending requests.");return;}for(ProductionRequest r:a)System.out.println(r.getRequestId()+" | "+r.getProductName()+" | "+r.getQuantity()+" | "+r.getPriority());}
}
